export interface DemoResult {
  accountId: string;
  inserted: number;
  alreadyLoaded: boolean;
}

export const loadDemoData = (): DemoResult => {
  const existing = db.select().from(accounts).where(eq(accounts.broker, DEMO_BROKER)).get();
  if (existing) {
    if (existing.archivedAt)
      db.update(accounts).set({ archivedAt: null }).where(eq(accounts.id, existing.id)).run();
    return { accountId: existing.id, inserted: 0, alreadyLoaded: true };
  }

  const id = newId();
  db.insert(accounts)
    .values({
      id,
      name: "Futures Trade Tracker",
      broker: DEMO_BROKER,
      kind: "manual",
      currency: "USD",
      initialBalance: 0,
      profitCalcMethod: "fifo",
      credentialsEnc: null,
      autoSync: false,
      createdAt: nowIso(),
    })
    .run();

  let inserted = 0;
  for (const trade of TRADES) {
    const sideIn = trade.direction === "long" ? "buy" : "sell";
    const sideOut = trade.direction === "long" ? "sell" : "buy";
    const fills: ImportedExecution[] = [
      {
        symbol: trade.symbol,
        side: sideIn,
        quantity: trade.quantity,
        price: trade.entry,
        fee: 0,
        executedAt: trade.openedAt,
        assetClass: trade.assetClass,
      },
      {
        symbol: trade.symbol,
        side: sideOut,
        quantity: trade.quantity,
        price: trade.exit,
        fee: 0,
        executedAt: trade.closedAt,
        assetClass: trade.assetClass,
      },
    ];
    inserted += insertExecutions(id, fills, "manual", trade.notes, { preserveFees: true }).inserted;
  }

  return { accountId: id, inserted, alreadyLoaded: false };
};
